#include <stdio.h>

int main() {
    int a[] = {1, 1, 2, 3, 3, 3, 4};
    int n = 7;
    int write = 1;
    for (int read = 1; read < n; read++) {
        if (a[read] != a[write - 1]) {
            a[write++] = a[read];
        }
    }
    for (int i = 0; i < write; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
